    ,sum(ads_imp_cnt_999) as ads_imp_cnt_999
    ,sum(ads_click_cnt_999) as ads_click_cnt_999
    ,sum(case when ads_order_cnt_999 > 0 then 1 else 0 end) as ads_order_uu_999
    ,sum(case when ads_imp_cnt_999 > 0 then 1 else 0 end) as ads_imp_uu_999
    ,sum(case when ads_click_cnt_999 > 0 then 1 else 0 end) as ads_click_uu_999
    ,sum(ads_total_location_999) as ads_total_location_999
    ,sum(ads_broad_order_cnt_999) as ads_broad_order_cnt_999
    ,sum(target_cir_999) / sum(target_cir_cnt_999) as target_cir_999
    ,sum(broad_advv_cost_999) as broad_advv_cost_999
    ,sum(broad_advv_gmv_999) as broad_advv_gmv_999
    ,sum(sum_deduction_price_usd_999) as sum_deduction_price_usd_999
    ,sum(sum_bid_price_usd_999) as sum_bid_price_usd_999
    ,sum(cnt_deduction_price_999) as cnt_deduction_price_999
    ,sum(cnt_bid_price_999) as cnt_bid_price_999
    ,sum(padvv_cost_999) as padvv_cost_999
    ,sum(broad_advv_cost_excl_outlier_999)  as broad_advv_cost_excl_outlier_999
    ,sum(broad_advv_cost_7d_999)as broad_advv_cost_7d_999
    ,sum(top20_ads_imp_cnt_999) as top20_ads_imp_cnt_999
    ,sum(top20_ads_total_location_999) as top20_ads_total_location_999
    ,sum(deepadvv_999) as deepadvv_999
    ,sum(valid_ads_imp_cnt_999) as valid_ads_imp_cnt_999
FROM 
