INSERT OVERWRITE TABLE ${schema}.ads_sr_data_warehouse_search_rcmd_abtest_card_type_advv_metrics_1d
PARTITION (
    grass_region = ${grass_region},
    local_date = ${local_date},
    domain,
    outlier
)
SELECT
/*+REPARTITION(8)*/
    feature_group
    ,exp_group_id
    ,main_product_type
    ,product_type
    ,card_type

    ,revenue_usd 
    ,broad_gmv_usd 
    ,ads_gmv_usd 
    ,ads_order_cnt
    ,ads_imp_cnt
    ,ads_click_cnt
    ,ads_order_uu
    ,ads_imp_uu
    ,ads_click_uu
    ,ads_total_location
    ,target_cir 
    ,broad_advv_cost
    ,broad_advv_gmv
    ,sum_deduction_price_usd  
    ,sum_bid_price_usd 
    ,cnt_deduction_price 
    ,cnt_bid_price 
    ,padvv_cost
    ,broad_advv_cost_excl_outlier 	
    ,broad_advv_cost_7d
    ,top20_ads_imp_cnt
    ,top20_ads_total_location
    ,deepadvv
    ,voucher_type
    ,valid_ads_imp_cnt
    ,ads_broad_order_cnt

    ,domain
    ,'1' AS outlier
FROM
    ads_exp_${grass_region_without_quote}
UNION ALL 
SELECT
/*+REPARTITION(8)*/
    feature_group
    ,exp_group_id
    ,main_product_type
    ,product_type
    ,card_type

    ,revenue_usd_999
    ,broad_gmv_usd_999
    ,ads_gmv_usd_999
    ,ads_order_cnt_999
    ,ads_imp_cnt_999
    ,ads_click_cnt_999
    ,ads_order_uu_999
    ,ads_imp_uu_999
    ,ads_click_uu_999
    ,ads_total_location_999
    ,target_cir_999
    ,broad_advv_cost_999
    ,broad_advv_gmv_999
    ,sum_deduction_price_usd_999 
    ,sum_bid_price_usd_999
    ,cnt_deduction_price_999
    ,cnt_bid_price_999
    ,padvv_cost_999
    ,broad_advv_cost_excl_outlier_999
    ,broad_advv_cost_7d_999
    ,top20_ads_imp_cnt_999
    ,top20_ads_total_location_999
    ,deepadvv_999
    ,voucher_type
    ,valid_ads_imp_cnt_999
    ,ads_broad_order_cnt_999

    ,domain
    ,'0.999' AS outlier
FROM
    ads_exp_${grass_region_without_quote}
